use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(author = "Tony Crisci")]
#[command(version = "1.0")]
#[command(about = "Make your i3 config a bit more stylish", long_about = None)]
struct Args {
    /// The theme to use
    theme: Option<String>,

    /// Prints help information
    #[arg(short, long)]
    help: bool,

    /// Print a list of all available themes
    #[arg(short = 'l', long)]
    list_all: bool,

    /// Apply the theme by reloading the config
    #[arg(short = 'r', long)]
    reload: bool,

    /// Set the output file to the path of the input file
    #[arg(short = 's', long)]
    save: bool,

    /// Prints version information
    #[arg(short = 'V', long)]
    version: bool,

    /// The config file the theme should be applied to. Defaults to the default i3 location.
    #[arg(short = 'c', long)]
    config: Option<String>,

    /// Apply the theme, attempt to validate the result, and write it to <file>
    #[arg(short = 'o', long)]
    output: Option<String>,

    /// Prints an i3-style theme based on the given config suitable for sharing with others
    #[arg(short = 't', long)]
    to_theme: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
enum ColorName {
    DarkGray,
    DarkSlateGray,
    White,
    DarkSlateBlue,
    LightGray,
    IndianRed,
    Wheat,
    Black,
    MediumPurple,
    Burlywood,
    Separator,
    Background,
    Statusline,
    FocusedWorkspace,
    ActiveWorkspace,
    InactiveWorkspace,
    UrgentWorkspace,
    Focused,
    FocusedInactive,
    Unfocused,
    Urgent,
}

impl ColorName {
    fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "darkgray" => Some(ColorName::DarkGray),
            "darkslategray" => Some(ColorName::DarkSlateGray),
            "white" => Some(ColorName::White),
            "darkslateblue" => Some(ColorName::DarkSlateBlue),
            "lightgray" => Some(ColorName::LightGray),
            "indianred" => Some(ColorName::IndianRed),
            "wheat" => Some(ColorName::Wheat),
            "black" => Some(ColorName::Black),
            "mediumpurple" => Some(ColorName::MediumPurple),
            "burlywood" => Some(ColorName::Burlywood),
            "separator" => Some(ColorName::Separator),
            "background" => Some(ColorName::Background),
            "statusline" => Some(ColorName::Statusline),
            "focused_workspace" => Some(ColorName::FocusedWorkspace),
            "active_workspace" => Some(ColorName::ActiveWorkspace),
            "inactive_workspace" => Some(ColorName::InactiveWorkspace),
            "urgent_workspace" => Some(ColorName::UrgentWorkspace),
            "focused" => Some(ColorName::Focused),
            "focused_inactive" => Some(ColorName::FocusedInactive),
            "unfocused" => Some(ColorName::Unfocused),
            "urgent" => Some(ColorName::Urgent),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
struct Theme {
    meta: Option<String>,
    colors: HashMap<ColorName, String>,
    window_colors: HashMap<ColorName, WindowColors>,
    bar_colors: HashMap<ColorName, BarColors>,
}

#[derive(Debug, Clone)]
struct WindowColors {
    border: String,
    background: String,
    text: String,
    indicator: String,
}

#[derive(Debug, Clone)]
struct BarColors {
    background: String,
    statusline: String,
    separator: String,
    focused_workspace: String,
    active_workspace: String,
    inactive_workspace: String,
    urgent_workspace: String,
}

fn parse_theme_file(path: &str) -> Result<Theme, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Could not open theme: {} - {}", path, e))?;

    let mut theme = Theme {
        meta: None,
        colors: HashMap::new(),
        window_colors: HashMap::new(),
        bar_colors: HashMap::new(),
    };

    let mut current_section = None;
    let mut current_subsection = None;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("---") {
            continue;
        }
        if line.is_empty() {
            continue;
        }

        if line.starts_with("meta:") {
            current_section = Some("meta");
            continue;
        }
        if line.starts_with("colors:") {
            current_section = Some("colors");
            continue;
        }
        if line.starts_with("window_colors:") {
            current_section = Some("window_colors");
            continue;
        }
        if line.starts_with("bar_colors:") {
            current_section = Some("bar_colors");
            continue;
        }

        if current_section == Some("meta") {
            if line.starts_with("description:") {
                let desc = line.trim_start_matches("description:").trim();
                theme.meta = Some(desc.to_string());
            }
        } else if current_section == Some("colors") {
            if line.starts_with("darkgray:") {
                let val = line.trim_start_matches("darkgray:").trim();
                theme.colors.insert(ColorName::DarkGray, val.to_string());
            } else if line.starts_with("darkslategray:") {
                let val = line.trim_start_matches("darkslategray:").trim();
                theme.colors.insert(ColorName::DarkSlateGray, val.to_string());
            } else if line.starts_with("white:") {
                let val = line.trim_start_matches("white:").trim();
                theme.colors.insert(ColorName::White, val.to_string());
            } else if line.starts_with("darkslateblue:") {
                let val = line.trim_start_matches("darkslateblue:").trim();
                theme.colors.insert(ColorName::DarkSlateBlue, val.to_string());
            } else if line.starts_with("lightgray:") {
                let val = line.trim_start_matches("lightgray:").trim();
                theme.colors.insert(ColorName::LightGray, val.to_string());
            } else if line.starts_with("indianred:") {
                let val = line.trim_start_matches("indianred:").trim();
                theme.colors.insert(ColorName::IndianRed, val.to_string());
            } else if line.starts_with("wheat:") {
                let val = line.trim_start_matches("wheat:").trim();
                theme.colors.insert(ColorName::Wheat, val.to_string());
            } else if line.starts_with("black:") {
                let val = line.trim_start_matches("black:").trim();
                theme.colors.insert(ColorName::Black, val.to_string());
            } else if line.starts_with("mediumpurple:") {
                let val = line.trim_start_matches("mediumpurple:").trim();
                theme.colors.insert(ColorName::MediumPurple, val.to_string());
            } else if line.starts_with("burlywood:") {
                let val = line.trim_start_matches("burlywood:").trim();
                theme.colors.insert(ColorName::Burlywood, val.to_string());
            }
        } else if current_section == Some("window_colors") {
            if line.starts_with("focused:") {
                current_subsection = Some("focused");
                continue;
            } else if line.starts_with("focused_inactive:") {
                current_subsection = Some("focused_inactive");
                continue;
            } else if line.starts_with("unfocused:") {
                current_subsection = Some("unfocused");
                continue;
            } else if line.starts_with("urgent:") {
                current_subsection = Some("urgent");
                continue;
            }
        } else if current_section == Some("window_colors") && current_subsection.is_some() {
            if let Some(subsection) = current_subsection {
                if line.starts_with("border:") {
                    let val = line.trim_start_matches("border:").trim();
                    if let Some(color_name) = ColorName::from_str(subsection) {
                        if let Some(window_colors) = theme.window_colors.get_mut(&color_name) {
                            window_colors.border = val.to_string();
                        }
                    }
                } else if line.starts_with("background:") {
                    let val = line.trim_start_matches("background:").trim();
                    if let Some(color_name) = ColorName::from_str(subsection) {
                        if let Some(window_colors) = theme.window_colors.get_mut(&color_name) {
                            window_colors.background = val.to_string();
                        }
                    }
                } else if line.starts_with("text:") {
                    let val = line.trim_start_matches("text:").trim();
                    if let Some(color_name) = ColorName::from_str(subsection) {
                        if let Some(window_colors) = theme.window_colors.get_mut(&color_name) {
                            window_colors.text = val.to_string();
                        }
                    }
                } else if line.starts_with("indicator:") {
                    let val = line.trim_start_matches("indicator:").trim();
                    if let Some(color_name) = ColorName::from_str(subsection) {
                        if let Some(window_colors) = theme.window_colors.get_mut(&color_name) {
                            window_colors.indicator = val.to_string();
                        }
                    }
                }
            }
        } else if current_section == Some("bar_colors") {
            if line.starts_with("background:") {
                let val = line.trim_start_matches("background:").trim();
                theme.bar_colors.insert(ColorName::Background, BarColors {
                    background: val.to_string(),
                    statusline: String::new(),
                    separator: String::new(),
                    focused_workspace: String::new(),
                    active_workspace: String::new(),
                    inactive_workspace: String::new(),
                    urgent_workspace: String::new(),
                });
            } else if line.starts_with("statusline:") {
                let val = line.trim_start_matches("statusline:").trim();
                if let Some(bar_colors) = theme.bar_colors.get_mut(&ColorName::Background) {
                    bar_colors.statusline = val.to_string();
                }
            } else if line.starts_with("separator:") {
                let val = line.trim_start_matches("separator:").trim();
                if let Some(bar_colors) = theme.bar_colors.get_mut(&ColorName::Background) {
                    bar_colors.separator = val.to_string();
                }
            } else if line.starts_with("focused_workspace:") {
                current_subsection = Some("focused_workspace");
                continue;
            } else if line.starts_with("active_workspace:") {
                current_subsection = Some("active_workspace");
                continue;
            } else if line.starts_with("inactive_workspace:") {
                current_subsection = Some("inactive_workspace");
                continue;
            } else if line.starts_with("urgent_workspace:") {
                current_subsection = Some("urgent_workspace");
                continue;
            }
        } else if current_section == Some("bar_colors") && current_subsection.is_some() {
            if let Some(subsection) = current_subsection {
                if line.starts_with("border:") {
                    let val = line.trim_start_matches("border:").trim();
                    if let Some(bar_colors) = theme.bar_colors.get_mut(&ColorName::Background) {
                        if let Some(color_name) = ColorName::from_str(subsection) {
                            bar_colors.focused_workspace = val.to_string();
                        }
                    }
                } else if line.starts_with("background:") {
                    let val = line.trim_start_matches("background:").trim();
                    if let Some(bar_colors) = theme.bar_colors.get_mut(&ColorName::Background) {
                        if let Some(color_name) = ColorName::from_str(subsection) {
                            bar_colors.focused_workspace = val.to_string();
                        }
                    }
                } else if line.starts_with("text:") {
                    let val = line.trim_start_matches("text:").trim();
                    if let Some(bar_colors) = theme.bar_colors.get_mut(&ColorName::Background) {
                        if let Some(color_name) = ColorName::from_str(subsection) {
                            bar_colors.focused_workspace = val.to_string();
                        }
                    }
                }
            }
        }
    }

    Ok(theme)
}

fn parse_config_file(path: &str) -> Result<String, String> {
    fs::read_to_string(path)
        .map_err(|e| format!("Could not open config: {} - {}", path, e))
}

fn get_default_config_path() -> String {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/user".to_string());
    format!("{}/.config/i3/config", home)
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(),
        "alphare".to_string(),
        "ubuntu".to_string(),
        "flat-gray".to_string(),
        "purple".to_string(),
        "archlinux".to_string(),
        "default".to_string(),
        "debian".to_string(),
        "oceanic-next".to_string(),
        "base16-tomorrow".to_string(),
        "okraits".to_string(),
        "icelines".to_string(),
        "solarized".to_string(),
        "deep-purple".to_string(),
        "tomorrow-night-80s".to_string(),
        "seti".to_string(),
        "lime".to_string(),
        "gruvbox".to_string(),
        "mate".to_string(),
    ]
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    // Remove existing client.* lines
    result = result
        .lines()
        .filter(|line| !line.starts_with("client."))
        .collect::<Vec<_>>()
        .join("\n");

    // Add new client.* lines
    let client_colors = vec![
        ("client.focused", &theme.window_colors.get(&ColorName::Focused).unwrap_or(&WindowColors {
            border: "#664477".to_string(),
            background: "#664477".to_string(),
            text: "#CCCCCC".to_string(),
            indicator: "#E7D8B1".to_string(),
        })),
        ("client.focused_inactive", &theme.window_colors.get(&ColorName::FocusedInactive).unwrap_or(&WindowColors {
            border: "#E7D8B1".to_string(),
            background: "#E7D8B1".to_string(),
            text: "#181715".to_string(),
            indicator: "#A074C4".to_string(),
        })),
        ("client.unfocused", &theme.window_colors.get(&ColorName::Unfocused).unwrap_or(&WindowColors {
            border: "#222133".to_string(),
            background: "#222133".to_string(),
            text: "#AAAAAA".to_string(),
            indicator: "#A074C4".to_string(),
        })),
        ("client.urgent", &theme.window_colors.get(&ColorName::Urgent).unwrap_or(&WindowColors {
            border: "#CE4045".to_string(),
            background: "#CE4045".to_string(),
            text: "#E7D8B1".to_string(),
            indicator: "#DCCD69".to_string(),
        })),
    ];

    for (name, colors) in client_colors {
        let border = colors.border.as_str();
        let background = colors.background.as_str();
        let text = colors.text.as_str();
        let indicator = colors.indicator.as_str();
        result.push_str(&format!("\n{} {} {} {} {}", name, border, background, text, indicator));
    }

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    let output = process::Command::new("i3")
        .args(&["-C", "-c", config_path])
        .output()
        .map_err(|e| format!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, e))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, stderr));
    }

    Ok(())
}

fn main() {
    let args = Args::parse();

    if args.help {
        println!("{}", Args::command().render_help());
        process::exit(0);
    }

    if args.version {
        println!("i3-style 1.0");
        process::exit(0);
    }

    if args.list_all {
        println!("\nAvailable themes:\n");
        for theme in get_available_themes() {
            let description = match theme.as_str() {
                "slate" => "Slate theme by Jody Ribton <jody@ribton.me>",
                "alphare" => "A beige theme by Alphare",
                "ubuntu" => "Ubuntu theme by lasers",
                "flat-gray" => "flat gray based theme",
                "purple" => "Purple theme by AAlakkad <http://aalakkad.me>",
                "archlinux" => "Archlinux theme by okraits <http://okraits.de>",
                "default" => "Default theme for i3wm <http://i3wm.org>",
                "debian" => "Debian theme by lasers",
                "oceanic-next" => "Theme by Valentin Weber inspired by voronianski (https://github.com/voronianski/oceanic-next-color-scheme)",
                "base16-tomorrow" => "Base16 Tomorrow, by Chris Kempson (http://chriskempson.com)",
                "okraits" => "A simple theme by okraits <http://okraits.de>",
                "icelines" => "icelines theme by mbfraga",
                "solarized" => "Solarized theme by lasers",
                "deep-purple" => "Inspired by the Purple and Default themes. By jcpst <http://jcpst.com>",
                "tomorrow-night-80s" => "Tomorrow Night 80s theme by jmfurlott <http://jmfurlott.com>",
                "seti" => "seti theme by Jody Ribton - based on the seti Atom theme at https://atom.io/themes/seti-ui",
                "lime" => "Lime theme by wei2912 <http://wei2912.github.io>, based on Archlinux theme by okraits <http://okraits.de>",
                "gruvbox" => "Made by freeware-preacher <https://github.com/freeware-preacher> to match gruvbox by morhetz <https://github.com/morhetz>",
                "mate" => "Theme for blending i3 into MATE",
                _ => "",
            };
            println!("  {:<18} - {}", theme, description);
        }
        process::exit(0);
    }

    if args.to_theme.is_some() {
        let config_path = args.to_theme.unwrap_or_else(|| get_default_config_path());
        let config = match parse_config_file(&config_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("{}", e);
                process::exit(1);
            }
        };

        // Parse the config to extract colors
        let mut window_colors = HashMap::new();
        let mut bar_colors = HashMap::new();

        // Extract window colors
        for line in config.lines() {
            if line.starts_with("client.focused") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 5 {
                    window_colors.insert(ColorName::Focused, WindowColors {
                        border: parts[1].to_string(),
                        background: parts[2].to_string(),
                        text: parts[3].to_string(),
                        indicator: parts[4].to_string(),
                    });
                }
            } else if line.starts_with("client.focused_inactive") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 5 {
                    window_colors.insert(ColorName::FocusedInactive, WindowColors {
                        border: parts[1].to_string(),
                        background: parts[2].to_string(),
                        text: parts[3].to_string(),
                        indicator: parts[4].to_string(),
                    });
                }
            } else if line.starts_with("client.unfocused") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 5 {
                    window_colors.insert(ColorName::Unfocused, WindowColors {
                        border: parts[1].to_string(),
                        background: parts[2].to_string(),
                        text: parts[3].to_string(),
                        indicator: parts[4].to_string(),
                    });
                }
            } else if line.starts_with("client.urgent") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 5 {
                    window_colors.insert(ColorName::Urgent, WindowColors {
                        border: parts[1].to_string(),
                        background: parts[2].to_string(),
                        text: parts[3].to_string(),
                        indicator: parts[4].to_string(),
                    });
                }
            }
        }

        // Extract bar colors
        let mut in_bar_colors = false;
        for line in config.lines() {
            if line.starts_with("bar {") {
                in_bar_colors = true;
                continue;
            }
            if line.starts_with("}") && in_bar_colors {
                in_bar_colors = false;
                continue;
            }
            if in_bar_colors && line.starts_with("colors {") {
                continue;
            }
            if in_bar_colors && line.starts_with("}") {
                continue;
            }
            if in_bar_colors {
                if line.starts_with("separator") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        bar_colors.insert(ColorName::Separator, parts[1].to_string());
                    }
                } else if line.starts_with("background") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        bar_colors.insert(ColorName::Background, parts[1].to_string());
                    }
                } else if line.starts_with("statusline") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        bar_colors.insert(ColorName::Statusline, parts[1].to_string());
                    }
                } else if line.starts_with("focused_workspace") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        bar_colors.insert(ColorName::FocusedWorkspace, format!("{} {} {} {}", parts[1], parts[2], parts[3], parts[4]));
                    }
                } else if line.starts_with("active_workspace") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        bar_colors.insert(ColorName::ActiveWorkspace, format!("{} {} {} {}", parts[1], parts[2], parts[3], parts[4]));
                    }
                } else if line.starts_with("inactive_workspace") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        bar_colors.insert(ColorName::InactiveWorkspace, format!("{} {} {} {}", parts[1], parts[2], parts[3], parts[4]));
                    }
                } else if line.starts_with("urgent_workspace") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        bar_colors.insert(ColorName::UrgentWorkspace, format!("{} {} {} {}", parts[1], parts[2], parts[3], parts[4]));
                    }
                }
            }
        }

        // Generate theme YAML
        let mut output = String::from("---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\n");
        output.push_str("colors:\n");
        if let Some(color) = window_colors.get(&ColorName::Focused) {
            output.push_str(&format!("  darkgray: \"{}\"\n", color.border));
            output.push_str(&format!("  darkslategray: \"{}\"\n", color.background));
            output.push_str(&format!("  white: \"{}\"\n", color.text));
            output.push_str(&format!("  darkslateblue: \"{}\"\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::FocusedInactive) {
            output.push_str(&format!("  wheat: \"{}\"\n", color.border));
            output.push_str(&format!("  wheat: \"{}\"\n", color.background));
            output.push_str(&format!("  black: \"{}\"\n", color.text));
            output.push_str(&format!("  mediumpurple: \"{}\"\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::Unfocused) {
            output.push_str(&format!("  darkslategray: \"{}\"\n", color.border));
            output.push_str(&format!("  darkslategray: \"{}\"\n", color.background));
            output.push_str(&format!("  darkgray: \"{}\"\n", color.text));
            output.push_str(&format!("  mediumpurple: \"{}\"\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::Urgent) {
            output.push_str(&format!("  indianred: \"{}\"\n", color.border));
            output.push_str(&format!("  indianred: \"{}\"\n", color.background));
            output.push_str(&format!("  wheat: \"{}\"\n", color.text));
            output.push_str(&format!("  burlywood: \"{}\"\n", color.indicator));
        }
        output.push_str("window_colors:\n");
        if let Some(color) = window_colors.get(&ColorName::Focused) {
            output.push_str("  focused:\n");
            output.push_str(&format!("    border: {}\n", color.border));
            output.push_str(&format!("    background: {}\n", color.background));
            output.push_str(&format!("    text: {}\n", color.text));
            output.push_str(&format!("    indicator: {}\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::FocusedInactive) {
            output.push_str("  focused_inactive:\n");
            output.push_str(&format!("    border: {}\n", color.border));
            output.push_str(&format!("    background: {}\n", color.background));
            output.push_str(&format!("    text: {}\n", color.text));
            output.push_str(&format!("    indicator: {}\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::Unfocused) {
            output.push_str("  unfocused:\n");
            output.push_str(&format!("    border: {}\n", color.border));
            output.push_str(&format!("    background: {}\n", color.background));
            output.push_str(&format!("    text: {}\n", color.text));
            output.push_str(&format!("    indicator: {}\n", color.indicator));
        }
        if let Some(color) = window_colors.get(&ColorName::Urgent) {
            output.push_str("  urgent:\n");
            output.push_str(&format!("    border: {}\n", color.border));
            output.push_str(&format!("    background: {}\n", color.background));
            output.push_str(&format!("    text: {}\n", color.text));
            output.push_str(&format!("    indicator: {}\n", color.indicator));
        }
        output.push_str("bar_colors:\n");
        if let Some(color) = bar_colors.get(&ColorName::Background) {
            output.push_str(&format!("  background: {}\n", color));
        }
        if let Some(color) = bar_colors.get(&ColorName::Statusline) {
            output.push_str(&format!("  statusline: {}\n", color));
        }
        if let Some(color) = bar_colors.get(&ColorName::Separator) {
            output.push_str(&format!("  separator: {}\n", color));
        }
        if let Some(color) = bar_colors.get(&ColorName::FocusedWorkspace) {
            output.push_str("  focused_workspace:\n");
            let parts: Vec<&str> = color.split_whitespace().collect();
            if parts.len() >= 4 {
                output.push_str(&format!("    border: {}\n", parts[1]));
                output.push_str(&format!("    background: {}\n", parts[2]));
                output.push_str(&format!("    text: {}\n", parts[3]));
            }
        }
        if let Some(color) = bar_colors.get(&ColorName::UrgentWorkspace) {
            output.push_str("  urgent_workspace:\n");
            let parts: Vec<&str> = color.split_whitespace().collect();
            if parts.len() >= 4 {
                output.push_str(&format!("    border: {}\n", parts[1]));
                output.push_str(&format!("    background: {}\n", parts[2]));
                output.push_str(&format!("    text: {}\n", parts[3]));
            }
        }

        if let Some(ref output_path) = args.output {
            let mut file = match fs::File::create(output_path) {
                Ok(f) => f,
                Err(e) => {
                    eprintln!("Could not write to {}: {}", output_path, e);
                    process::exit(1);
                }
            };
            if let Err(e) = file.write_all(output.as_bytes()) {
                eprintln!("Could not write to {}: {}", output_path, e);
                process::exit(1);
            }
        } else {
            print!("{}", output);
        }

        process::exit(0);
    }

    // Get theme
    let theme_path = match &args.theme {
        Some(t) => t.clone(),
        None => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let theme = match parse_theme_file(&theme_path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{}", e);
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
            process::exit(1);
        }
    };

    // Get config path
    let config_path = args.config.unwrap_or_else(get_default_config_path);

    // Parse config
    let config = match parse_config_file(&config_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    // Apply theme
    let output = apply_theme_to_config(&config, &theme);

    // Validate config
    if args.reload {
        if let Err(e) = validate_config(&config_path) {
            eprintln!("{}", e);
            process::exit(1);
        }
    }

    // Write output
    let output_path = if args.save {
        config_path.clone()
    } else {
        args.output.unwrap_or_else(|| config_path.clone())
    };

    let mut file = match fs::File::create(&output_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Could not write to {}: {}", output_path, e);
            process::exit(1);
        }
    };

    if let Err(e) = file.write_all(output.as_bytes()) {
        eprintln!("Could not write to {}: {}", output_path, e);
        process::exit(1);
    }

    println!("saving config at {} to /tmp/i3-style/{}/config-input", config_path, std::process::id());

    // Validate if output is different from input
    if output_path != config_path {
        if let Err(e) = validate_config(&output_path) {
            eprintln!("{}", e);
            process::exit(1);
        }
    }

    process::exit(0);
}
RUSTEOF"}

