    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];

        if arg == "-h" || arg == "--help" {
            result.help = true;
            i += 1;
            continue;
        }

        if arg == "-l" || arg == "--list-all" {
            result.list_all = true;
            i += 1;
            continue;
        }

        if arg == "-r" || arg == "--reload" {
            result.reload = true;
            i += 1;
            continue;
