fn parse_config_file(path: &str) -> Result<String, String> {
    fs::read_to_string(path)
        .map_err(|e| format!("Could not open config: {} - {}", path, e))
}

fn get_default_config_path() -> String {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/user".to_string());
    format!("{}/.config/i3/config", home)
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(),
        "alphare".to_string(),
        "ubuntu".to_string(),
        "flat-gray".to_string(),
        "purple".to_string(),
        "archlinux".to_string(),
        "default".to_string(),
        "debian".to_string(),
        "oceanic-next".to_string(),
        "base16-tomorrow".to_string(),
        "okraits".to_string(),
        "icelines".to_string(),
        "solarized".to_string(),
        "deep-purple".to_string(),
        "tomorrow-night-80s".to_string(),
        "seti".to_string(),
        "lime".to_string(),
        "gruvbox".to_string(),
        "mate".to_string(),
    ]
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    // Remove existing client.* lines
    result = result
        .lines()
        .filter(|line| !line.starts_with("client."))
        .collect::<Vec<_>>()
        .join("\n");

    // Add new client.* lines
    let focused = theme.window_colors.get(&ColorName::Focused).unwrap_or(&WindowColors {
        border: "#664477".to_string(),
        background: "#664477".to_string(),
        text: "#CCCCCC".to_string(),
        indicator: "#E7D8B1".to_string(),
    });
    let focused_inactive = theme.window_colors.get(&ColorName::FocusedInactive).unwrap_or(&WindowColors {
        border: "#E7D8B1".to_string(),
        background: "#E7D8B1".to_string(),
        text: "#181715".to_string(),
        indicator: "#A074C4".to_string(),
    });
    let unfocused = theme.window_colors.get(&ColorName::Unfocused).unwrap_or(&WindowColors {
        border: "#222133".to_string(),
        background: "#222133".to_string(),
        text: "#AAAAAA".to_string(),
        indicator: "#A074C4".to_string(),
    });
    let urgent = theme.window_colors.get(&ColorName::Urgent).unwrap_or(&WindowColors {
        border: "#CE4045".to_string(),
        background: "#CE4045".to_string(),
        text: "#E7D8B1".to_string(),
        indicator: "#DCCD69".to_string(),
    });

    result.push_str(&format!("\nclient.focused {} {} {} {}", focused.border, focused.background, focused.text, focused.indicator));
    result.push_str(&format!("\nclient.focused_inactive {} {} {} {}", focused_inactive.border, focused_inactive.background, focused_inactive.text, focused_inactive.indicator));
    result.push_str(&format!("\nclient.unfocused {} {} {} {}", unfocused.border, unfocused.background, unfocused.text, unfocused.indicator));
    result.push_str(&format!("\nclient.urgent {} {} {} {}", urgent.border, urgent.background, urgent.text, urgent.indicator));

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    let output = process::Command::new("i3")
        .args(&["-C", "-c", config_path])
        .output()
        .map_err(|e| format!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, e))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, stderr));
    }

    Ok(())
}

fn print_help() {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [theme]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help        Prints help information");
    println!("    -l, --list-all    Print a list of all available themes");
    println!("    -r, --reload      Apply the theme by reloading the config");
    println!("    -s, --save        Set the output file to the path of the input file");
    println!("    -V, --version     Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.");
    println!("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>");
    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let parsed_args = parse_args(&args);

    if parsed_args.help {
        print_help();
        process::exit(0);
    }

    if parsed_args.version {
        println!("i3-style 1.0");
        process::exit(0);
