        if arg == "-V" || arg == "--version" {
            result.version = true;
            i += 1;
            continue;
        }

        if arg == "-c" || arg == "--config" {
            if i + 1 < args.len() {
                result.config = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: --config requires a value");
