    save: bool,
    version: bool,
    config: Option<String>,
    output: Option<String>,
    to_theme: Option<String>,
}

fn parse_args(args: &[String]) -> Args {
    let mut result = Args {
        theme: None,
        help: false,
        list_all: false,
        reload: false,
        save: false,
        version: false,
        config: None,
        output: None,
        to_theme: None,
    };

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];

        if arg == "-h" || arg == "--help" {
            result.help = true;
            i += 1;
            continue;
        }

        if arg == "-l" || arg == "--list-all" {
            result.list_all = true;
            i += 1;
            continue;
        }

        if arg == "-r" || arg == "--reload" {
            result.reload = true;
            i += 1;
            continue;
        }

        if arg == "-s" || arg == "--save" {
            result.save = true;
            i += 1;
            continue;
        }

        if arg == "-V" || arg == "--version" {
            result.version = true;
            i += 1;
            continue;
        }

        if arg == "-c" || arg == "--config" {
            if i + 1 < args.len() {
                result.config = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: --config requires a value");
