fn get_config_file() -> String {
    let default_config = "/etc/i3/config";
    let home_config = format!("/home/{}/.config/i3/config", env::var("USER").unwrap_or_else(|_| "user".to_string()));

    if Path::new(default_config).exists() {
        default_config.to_string()
    } else if Path::new(&home_config).exists() {
        home_config
    } else {
        default_config.to_string()
    }
}

fn get_output_file(args: &[String]) -> String {
    if args.iter().any(|a| a == "-s" || a == "--save") {
        get_config_file()
    } else {
        "/tmp/i3-style-output".to_string()
    }
}

fn apply_theme(config_file: &str, theme_name: &str, output_file: &str) -> Result<(), String> {
    let config_content = fs::read_to_string(config_file)
        .map_err(|e| format!("Could not read config file: {}", e))?;

    let theme = get_theme(theme_name)
        .map_err(|e| format!("Could not find theme: {}", e))?;

    let mut result = apply_theme_to_config(&config_content, &theme);

    let mut output = fs::File::create(output_file)
        .map_err(|e| format!("Could not create output file: {}", e))?;

    output.write_all(result.as_bytes())
        .map_err(|e| format!("Could not write output file: {}", e))?;

    Ok(())
}
