            "-r" | "--reload" => {
                reload = true;
            }
            "-s" | "--save" => {
                save = true;
            }
            "-V" | "--version" => {
                print_version();
                process::exit(0);
            }
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config = Some(args[i + 1].clone());
                    i += 1;
                }
