    let mut window_colors: HashMap<String, WindowColor> = HashMap::new();
    let mut bar_colors: HashMap<String, BarColor> = HashMap::new();

    for line in content.lines() {
        let trimmed = line.trim();

        if trimmed.starts_with("---") {
            continue;
        }

        if trimmed.starts_with("meta:") {
            in_meta = true;
            in_colors = false;
            in_window_colors = false;
            in_bar_colors = false;
            continue;
        }

        if trimmed.starts_with("colors:") {
            in_meta = false;
            in_colors = true;
