            in_meta = false;
            in_colors = false;
            in_window_colors = false;
            in_bar_colors = true;
            continue;
        }

        if in_meta && trimmed.starts_with("description:") {
            meta_desc = trimmed.split(':').nth(1).unwrap_or("").trim().to_string();
            continue;
        }

        if in_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            let value = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
            colors.insert(key, value);
            continue;
        }

        if in_window_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            window_colors.insert(key, WindowColor {
                border: String::new(),
                background: String::new(),
                text: String::new(),
                indicator: String::new(),
            });
            in_focused = false;
            in_focused_inactive = false;
            in_unfocused = false;
            in_urgent = false;
            continue;
        }

        if in_window_colors && trimmed.starts_with("    ") && !trimmed.starts_with("      ") {
            let key = trimmed.trim_start_matches("    ").trim_start_matches(':').trim().to_string();
            if let Some(wc) = window_colors.get_mut(&key) {
                if key == "focused" {
                    in_focused = true;
                } else if key == "focused_inactive" {
                    in_focused_inactive = true;
                } else if key == "unfocused" {
                    in_unfocused = true;
                } else if key == "urgent" {
                    in_urgent = true;
                }
            }
            continue;
        }

        if in_window_colors && trimmed.starts_with("      ") && !trimmed.starts_with("        ") {
            let key = trimmed.trim_start_matches("      ").trim_start_matches(':').trim().to_string();
            if let Some(wc) = window_colors.get_mut(&key) {
                if key == "border" {
                    wc.border = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "background" {
                    wc.background = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "text" {
                    wc.text = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "indicator" {
                    wc.indicator = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            bar_colors.insert(key, BarColor {
                background: String::new(),
                statusline: String::new(),
                separator: String::new(),
                focused_workspace: None,
                active_workspace: None,
                inactive_workspace: None,
                urgent_workspace: None,
            });
            in_focused_workspace = false;
            in_active_workspace = false;
            in_inactive_workspace = false;
            in_urgent_workspace = false;
            continue;
        }

        if in_bar_colors && trimmed.starts_with("    ") && !trimmed.starts_with("      ") {
            let key = trimmed.trim_start_matches("    ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "focused_workspace" {
                    in_focused_workspace = true;
                } else if key == "active_workspace" {
