                } else if key == "inactive_workspace" {
                    in_inactive_workspace = true;
                } else if key == "urgent_workspace" {
                    in_urgent_workspace = true;
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("      ") && !trimmed.starts_with("        ") {
            let key = trimmed.trim_start_matches("      ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "border" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                } else if key == "background" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                } else if key == "text" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("        ") && !trimmed.starts_with("          ") {
            let key = trimmed.trim_start_matches("        ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "border" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.border = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                } else if key == "background" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.background = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                } else if key == "text" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.text = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                }
            }
            continue;
        }
    }

    theme.meta = Some(Meta { description: meta_desc });
    theme.colors = Some(colors);
    theme.window_colors = Some(window_colors);
    theme.bar_colors = Some(bar_colors);

    Some(theme)
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    let lines: Vec<&str> = config.lines().collect();
    let mut in_bar = false;
    let mut in_colors = false;
    let mut bar_colors: HashMap<String, String> = HashMap::new();
    let mut workspace_colors: HashMap<String, Vec<String>> = HashMap::new();

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            continue;
        }

        if in_bar && trimmed == "}" {
            in_bar = false;
            in_colors = false;
            continue;
        }

        if in_bar && trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_colors && trimmed == "}" {
            in_colors = false;
            continue;
        }

        if in_colors {
            if trimmed.starts_with("separator") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(separator) = bc.get("separator") {
                        bar_colors.insert("separator".to_string(), separator.clone());
                    }
                }
            } else if trimmed.starts_with("background") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(background) = bc.get("background") {
                        bar_colors.insert("background".to_string(), background.clone());
                    }
                }
            } else if trimmed.starts_with("statusline") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(statusline) = bc.get("statusline") {
                        bar_colors.insert("statusline".to_string(), statusline.clone());
                    }
                }
            } else if trimmed.starts_with("focused_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(fws) = bc.get("focused_workspace") {
                        workspace_colors.insert("focused_workspace".to_string(), vec![
                            fws.border.clone(),
                            fws.background.clone(),
                            fws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("active_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(aws) = bc.get("active_workspace") {
                        workspace_colors.insert("active_workspace".to_string(), vec![
                            aws.border.clone(),
                            aws.background.clone(),
                            aws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("inactive_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(iws) = bc.get("inactive_workspace") {
                        workspace_colors.insert("inactive_workspace".to_string(), vec![
                            iws.border.clone(),
                            iws.background.clone(),
                            iws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("urgent_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(uws) = bc.get("urgent_workspace") {
                        workspace_colors.insert("urgent_workspace".to_string(), vec![
                            uws.border.clone(),
                            uws.background.clone(),
                            uws.text.clone(),
                        ]);
                    }
                }
            }
        }
    }

    for (key, value) in bar_colors {
        let old = format!("{} {}", key, value);
        let new = format!("{} #{}", key, value);
        result = result.replace(&old, &new);
    }

    for (key, colors) in workspace_colors {
        let old = format!("{} {}", key, colors[0]);
        let new = format!("{} #{} #{} #{}", key, colors[0], colors[1], colors[2]);
        result = result.replace(&old, &new);
    }

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    let i3_cmd = format!("i3 -C -c {}", config_path);

    let output = std::process::Command::new("sh")
        .arg("-c")
        .arg(&i3_cmd)
        .output();

    match output {
        Ok(out) => {
            if out.status.success() {
                Ok(())
            } else {
                Err(format!("Could not validate config with `{}`", i3_cmd))
            }
        }
        Err(_) => Err(format!("Could not validate config with `{}`", i3_cmd)),
    }
}

fn main() {
    let (theme, config, output, to_theme, list_all, reload, save) = parse_args();

    if list_all {
        print_list_all();
        process::exit(0);
    }

    if to_theme.is_some() {
        let config_path = config.as_deref().unwrap_or_else(|| get_default_config().as_str());
        let config_content = match fs::read_to_string(config_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Could not open config: {} - {}", config_path, e);
                process::exit(1);
            }
        };

        let theme = Theme {
            meta: Some(Meta {
                description: "AUTOMATICALLY GENERATED THEME".to_string(),
            }),
            colors: Some(HashMap::new()),
            window_colors: Some(HashMap::new()),
            bar_colors: Some(HashMap::new()),
        };

        let output_content = apply_theme_to_config(&config_content, &theme);
        println!("{}", output_content);
        process::exit(0);
    }

    let theme_name = theme.as_deref();
    let theme_path = theme.as_ref().map(|s| s.as_str());

    let theme = if let Some(path) = theme_path {
        load_theme_from_file(path)
    } else if let Some(name) = theme_name {
        get_theme_by_name(name)
    } else {
        eprintln!("No theme specified");
        process::exit(1);
    };

    let theme = match theme {
        Some(t) => t,
        None => {
            eprintln!("Could not open theme: {} - No such file or directory (os error 2)", theme_path.unwrap_or(""));
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
            process::exit(1);
        }
    };

    let config_path = config.as_deref().unwrap_or_else(|| get_default_config().as_str());

    let config_content = match fs::read_to_string(config_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let output_content = apply_theme_to_config(&config_content, &theme);

    if save {
        let output_path = config_path.to_string();
        match fs::write(&output_path, &output_content) {
            Ok(_) => {
                println!("saving config at {} to {}", config_path, output_path);
            }
            Err(e) => {
                eprintln!("Could not save config: {}", e);
                process::exit(1);
            }
        }
    } else if let Some(output) = &output {
        let output_dir = Path::new(output).parent().unwrap_or(Path::new("."));
        if !output_dir.exists() {
            match fs::create_dir_all(output_dir) {
                Ok(_) => {}
                Err(e) => {
                    eprintln!("Could not create output directory: {}", e);
                    process::exit(1);
                }
            }
        }

        match fs::write(output, &output_content) {
            Ok(_) => {
                println!("saving config at {} to {}", config_path, output);
            }
            Err(e) => {
                eprintln!("Could not write output: {}", e);
                process::exit(1);
            }
        }

        if reload {
            let i3_msg = "i3-msg reload".to_string();
            let output = std::process::Command::new("sh")
                .arg("-c")
                .arg(&i3_msg)
                .output();

            match output {
                Ok(out) => {
                    if !out.status.success() {
                        let stderr = std::str::from_utf8(&out.stderr).unwrap_or("");
                        eprintln!("Could not reload config with {}: {}", i3_msg, stderr);
                        process::exit(1);
                    }
                }
                Err(_) => {
                    eprintln!("Could not reload config with {}: No such file or directory (os error 2)", i3_msg);
                    process::exit(1);
                }
            }
        }

        if output.is_some() {
            if let Err(e) = validate_config(output) {
                eprintln!("{}", e);
                process::exit(1);
            }
        }
    } else {
        println!("{}", output_content);
    }
}

#[derive(Debug, Clone)]
struct Theme {
    meta: Option<Meta>,
    colors: Option<HashMap<String, String>>,
    window_colors: Option<HashMap<String, WindowColor>>,
    bar_colors: Option<HashMap<String, BarColor>>,
}

#[derive(Debug, Clone)]
struct Meta {
    description: String,
}

#[derive(Debug, Clone)]
struct WindowColor {
    border: String,
    background: String,
    text: String,
    indicator: String,
}

#[derive(Debug, Clone)]
struct BarColor {
    background: String,
    statusline: String,
    separator: String,
    focused_workspace: Option<WorkspaceColor>,
    active_workspace: Option<WorkspaceColor>,
    inactive_workspace: Option<WorkspaceColor>,
    urgent_workspace: Option<WorkspaceColor>,
}

#[derive(Debug, Clone)]
struct WorkspaceColor {
    border: String,
    background: String,
    text: String,
}

