use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::Write;
use std::path::Path;
use std::process;

fn print_help() {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [theme]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help        Prints help information");
    println!("    -l, --list-all    Print a list of all available themes");
    println!("    -r, --reload      Apply the theme by reloading the config");
    println!("    -s, --save        Set the output file to the path of the input file");
    println!("    -V, --version     Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.");
    println!("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>");
    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

fn print_version() {
    println!("i3-style 1.0");
}

fn print_list_all() {
    println!("\nAvailable themes:\n");
    let themes = vec![
        "slate", "alphare", "ubuntu", "flat-gray", "purple",
        "archlinux", "default", "debian", "oceanic-next",
        "base16-tomorrow", "okraits", "icelines", "solarized",
        "deep-purple", "tomorrow-night-80s", "seti", "lime",
        "gruvbox", "mate"
    ];
    for theme in themes {
        println!("  {} - {}", theme, theme);
    }
}

fn get_default_config() -> String {
    match env::var("HOME") {
        Ok(home) => format!("{}/.config/i3/config", home),
        Err(_) => "/home/user/.config/i3/config".to_string(),
    }
}

fn parse_args() -> (Option<String>, Option<String>, Option<String>, bool, bool, bool, bool) {
    let args: Vec<String> = env::args().collect();
    let mut theme = None;
    let mut config = None;
    let mut output = None;
    let mut to_theme = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-l" | "--list-all" => {
                list_all = true;
            }
            "-r" | "--reload" => {
                reload = true;
            }
            "-s" | "--save" => {
                save = true;
            }
            "-V" | "--version" => {
                print_version();
                process::exit(0);
            }
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-t" | "--to-theme" => {
                if i + 1 < args.len() {
                    to_theme = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            _ => {
                theme = Some(arg.clone());
            }
        }
        i += 1;
    }

    (theme, config, output, to_theme, list_all, reload, save)
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(), "alphare".to_string(), "ubuntu".to_string(),
        "flat-gray".to_string(), "purple".to_string(), "archlinux".to_string(),
        "default".to_string(), "debian".to_string(), "oceanic-next".to_string(),
        "base16-tomorrow".to_string(), "okraits".to_string(), "icelines".to_string(),
        "solarized".to_string(), "deep-purple".to_string(), "tomorrow-night-80s".to_string(),
        "seti".to_string(), "lime".to_string(), "gruvbox".to_string(), "mate".to_string()
    ]
}

fn get_theme_by_name(name: &str) -> Option<Theme> {
    let themes = get_available_themes();
    if themes.contains(&name.to_string()) {
        Some(Theme {
            meta: Some(Meta {
                description: format!("{} theme", name),
            }),
            colors: Some(HashMap::new()),
            window_colors: Some(HashMap::new()),
            bar_colors: Some(HashMap::new()),
        })
    } else {
        None
    }
}

fn load_theme_from_file(path: &str) -> Option<Theme> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return None,
    };

    // Simple YAML parser for our specific format
    let mut theme = Theme {
        meta: None,
        colors: None,
        window_colors: None,
        bar_colors: None,
    };

    let mut in_meta = false;
    let mut in_colors = false;
    let mut in_window_colors = false;
    let mut in_bar_colors = false;
    let mut in_focused = false;
    let mut in_focused_inactive = false;
    let mut in_unfocused = false;
    let mut in_urgent = false;
    let mut in_focused_workspace = false;
    let mut in_active_workspace = false;
    let mut in_inactive_workspace = false;
    let mut in_urgent_workspace = false;

    let mut meta_desc = String::new();
    let mut colors: HashMap<String, String> = HashMap::new();
    let mut window_colors: HashMap<String, WindowColor> = HashMap::new();
    let mut bar_colors: HashMap<String, BarColor> = HashMap::new();

    for line in content.lines() {
        let trimmed = line.trim();

        if trimmed.starts_with("---") {
            continue;
        }

        if trimmed.starts_with("meta:") {
            in_meta = true;
            in_colors = false;
            in_window_colors = false;
            in_bar_colors = false;
            continue;
        }

        if trimmed.starts_with("colors:") {
            in_meta = false;
            in_colors = true;
            in_window_colors = false;
            in_bar_colors = false;
            continue;
        }

        if trimmed.starts_with("window_colors:") {
            in_meta = false;
            in_colors = false;
            in_window_colors = true;
            in_bar_colors = false;
            continue;
        }

        if trimmed.starts_with("bar_colors:") {
            in_meta = false;
            in_colors = false;
            in_window_colors = false;
            in_bar_colors = true;
            continue;
        }

        if in_meta && trimmed.starts_with("description:") {
            meta_desc = trimmed.split(':').nth(1).unwrap_or("").trim().to_string();
            continue;
        }

        if in_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            let value = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
            colors.insert(key, value);
            continue;
        }

        if in_window_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            window_colors.insert(key, WindowColor {
                border: String::new(),
                background: String::new(),
                text: String::new(),
                indicator: String::new(),
            });
            in_focused = false;
            in_focused_inactive = false;
            in_unfocused = false;
            in_urgent = false;
            continue;
        }

        if in_window_colors && trimmed.starts_with("    ") && !trimmed.starts_with("      ") {
            let key = trimmed.trim_start_matches("    ").trim_start_matches(':').trim().to_string();
            if let Some(wc) = window_colors.get_mut(&key) {
                if key == "focused" {
                    in_focused = true;
                } else if key == "focused_inactive" {
                    in_focused_inactive = true;
                } else if key == "unfocused" {
                    in_unfocused = true;
                } else if key == "urgent" {
                    in_urgent = true;
                }
            }
            continue;
        }

        if in_window_colors && trimmed.starts_with("      ") && !trimmed.starts_with("        ") {
            let key = trimmed.trim_start_matches("      ").trim_start_matches(':').trim().to_string();
            if let Some(wc) = window_colors.get_mut(&key) {
                if key == "border" {
                    wc.border = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "background" {
                    wc.background = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "text" {
                    wc.text = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                } else if key == "indicator" {
                    wc.indicator = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("  ") && !trimmed.starts_with("    ") {
            let key = trimmed.trim_start_matches("  ").trim_start_matches(':').trim().to_string();
            bar_colors.insert(key, BarColor {
                background: String::new(),
                statusline: String::new(),
                separator: String::new(),
                focused_workspace: None,
                active_workspace: None,
                inactive_workspace: None,
                urgent_workspace: None,
            });
            in_focused_workspace = false;
            in_active_workspace = false;
            in_inactive_workspace = false;
            in_urgent_workspace = false;
            continue;
        }

        if in_bar_colors && trimmed.starts_with("    ") && !trimmed.starts_with("      ") {
            let key = trimmed.trim_start_matches("    ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "focused_workspace" {
                    in_focused_workspace = true;
                } else if key == "active_workspace" {
                    in_active_workspace = true;
                } else if key == "inactive_workspace" {
                    in_inactive_workspace = true;
                } else if key == "urgent_workspace" {
                    in_urgent_workspace = true;
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("      ") && !trimmed.starts_with("        ") {
            let key = trimmed.trim_start_matches("      ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "border" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                } else if key == "background" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                } else if key == "text" {
                    bc.focused_workspace = Some(WorkspaceColor {
                        border: String::new(),
                        background: String::new(),
                        text: String::new(),
                    });
                }
            }
            continue;
        }

        if in_bar_colors && trimmed.starts_with("        ") && !trimmed.starts_with("          ") {
            let key = trimmed.trim_start_matches("        ").trim_start_matches(':').trim().to_string();
            if let Some(bc) = bar_colors.get_mut(&key) {
                if key == "border" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.border = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                } else if key == "background" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.background = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                } else if key == "text" {
                    if let Some(ws) = bc.focused_workspace.as_mut() {
                        ws.text = trimmed.split(':').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
                    }
                }
            }
            continue;
        }
    }

    theme.meta = Some(Meta { description: meta_desc });
    theme.colors = Some(colors);
    theme.window_colors = Some(window_colors);
    theme.bar_colors = Some(bar_colors);

    Some(theme)
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    let lines: Vec<&str> = config.lines().collect();
    let mut in_bar = false;
    let mut in_colors = false;
    let mut bar_colors: HashMap<String, String> = HashMap::new();
    let mut workspace_colors: HashMap<String, Vec<String>> = HashMap::new();

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            continue;
        }

        if in_bar && trimmed == "}" {
            in_bar = false;
            in_colors = false;
            continue;
        }

        if in_bar && trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_colors && trimmed == "}" {
            in_colors = false;
            continue;
        }

        if in_colors {
            if trimmed.starts_with("separator") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(separator) = bc.get("separator") {
                        bar_colors.insert("separator".to_string(), separator.clone());
                    }
                }
            } else if trimmed.starts_with("background") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(background) = bc.get("background") {
                        bar_colors.insert("background".to_string(), background.clone());
                    }
                }
            } else if trimmed.starts_with("statusline") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(statusline) = bc.get("statusline") {
                        bar_colors.insert("statusline".to_string(), statusline.clone());
                    }
                }
            } else if trimmed.starts_with("focused_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(fws) = bc.get("focused_workspace") {
                        workspace_colors.insert("focused_workspace".to_string(), vec![
                            fws.border.clone(),
                            fws.background.clone(),
                            fws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("active_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(aws) = bc.get("active_workspace") {
                        workspace_colors.insert("active_workspace".to_string(), vec![
                            aws.border.clone(),
                            aws.background.clone(),
                            aws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("inactive_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(iws) = bc.get("inactive_workspace") {
                        workspace_colors.insert("inactive_workspace".to_string(), vec![
                            iws.border.clone(),
                            iws.background.clone(),
                            iws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("urgent_workspace") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    if let Some(uws) = bc.get("urgent_workspace") {
                        workspace_colors.insert("urgent_workspace".to_string(), vec![
                            uws.border.clone(),
                            uws.background.clone(),
                            uws.text.clone(),
                        ]);
                    }
                }
            }
        }
    }

    for (key, value) in bar_colors {
        let old = format!("{} {}", key, value);
        let new = format!("{} #{}", key, value);
        result = result.replace(&old, &new);
    }

    for (key, colors) in workspace_colors {
        let old = format!("{} {}", key, colors[0]);
        let new = format!("{} #{} #{} #{}", key, colors[0], colors[1], colors[2]);
        result = result.replace(&old, &new);
    }

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    let i3_cmd = format!("i3 -C -c {}", config_path);

    let output = std::process::Command::new("sh")
        .arg("-c")
        .arg(&i3_cmd)
        .output();

    match output {
        Ok(out) => {
            if out.status.success() {
                Ok(())
            } else {
                Err(format!("Could not validate config with `{}`", i3_cmd))
            }
        }
        Err(_) => Err(format!("Could not validate config with `{}`", i3_cmd)),
    }
}

fn main() {
    let (theme, config, output, to_theme, list_all, reload, save) = parse_args();

    if list_all {
        print_list_all();
        process::exit(0);
    }

    if to_theme.is_some() {
        let config_path = config.as_deref().unwrap_or_else(|| get_default_config().as_str());
        let config_content = match fs::read_to_string(config_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Could not open config: {} - {}", config_path, e);
                process::exit(1);
            }
        };

        let theme = Theme {
            meta: Some(Meta {
                description: "AUTOMATICALLY GENERATED THEME".to_string(),
            }),
            colors: Some(HashMap::new()),
            window_colors: Some(HashMap::new()),
            bar_colors: Some(HashMap::new()),
        };

        let output_content = apply_theme_to_config(&config_content, &theme);
        println!("{}", output_content);
        process::exit(0);
    }

    let theme_name = theme.as_deref();
    let theme_path = theme.as_ref().map(|s| s.as_str());

    let theme = if let Some(path) = theme_path {
        load_theme_from_file(path)
    } else if let Some(name) = theme_name {
        get_theme_by_name(name)
    } else {
        eprintln!("No theme specified");
        process::exit(1);
    };

    let theme = match theme {
        Some(t) => t,
        None => {
            eprintln!("Could not open theme: {} - No such file or directory (os error 2)", theme_path.unwrap_or(""));
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
            process::exit(1);
        }
    };

    let config_path = config.as_deref().unwrap_or_else(|| get_default_config().as_str());

    let config_content = match fs::read_to_string(config_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let output_content = apply_theme_to_config(&config_content, &theme);

    if save {
        let output_path = config_path.to_string();
        match fs::write(&output_path, &output_content) {
            Ok(_) => {
                println!("saving config at {} to {}", config_path, output_path);
            }
            Err(e) => {
                eprintln!("Could not save config: {}", e);
                process::exit(1);
            }
        }
    } else if let Some(output) = &output {
        let output_dir = Path::new(output).parent().unwrap_or(Path::new("."));
        if !output_dir.exists() {
            match fs::create_dir_all(output_dir) {
                Ok(_) => {}
                Err(e) => {
                    eprintln!("Could not create output directory: {}", e);
                    process::exit(1);
                }
            }
        }

        match fs::write(output, &output_content) {
            Ok(_) => {
                println!("saving config at {} to {}", config_path, output);
            }
            Err(e) => {
                eprintln!("Could not write output: {}", e);
                process::exit(1);
            }
        }

        if reload {
            let i3_msg = "i3-msg reload".to_string();
            let output = std::process::Command::new("sh")
                .arg("-c")
                .arg(&i3_msg)
                .output();

            match output {
                Ok(out) => {
                    if !out.status.success() {
                        let stderr = std::str::from_utf8(&out.stderr).unwrap_or("");
                        eprintln!("Could not reload config with {}: {}", i3_msg, stderr);
                        process::exit(1);
                    }
                }
                Err(_) => {
                    eprintln!("Could not reload config with {}: No such file or directory (os error 2)", i3_msg);
                    process::exit(1);
                }
            }
        }

        if output.is_some() {
            if let Err(e) = validate_config(output) {
                eprintln!("{}", e);
                process::exit(1);
            }
        }
    } else {
        println!("{}", output_content);
    }
}

