function.arguments:
{"command": "cd /workspace && cat > src/main.rs << 'EOF'
use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::Path;
use std::process;

#[derive(Debug, Clone)]
struct Meta {
    description: String,
}

#[derive(Debug, Clone)]
struct Colors {
    background: String,
    foreground: String,
    focused_border: String,
    focused_text: String,
    focused_background: String,
    active_border: String,
    active_text: String,
    active_background: String,
    inactive_border: String,
    inactive_text: String,
    inactive_background: String,
    urgent_border: String,
    urgent_text: String,
    urgent_background: String,
}

#[derive(Debug, Clone)]
struct WindowColors {
    focused: Option<Colors>,
    active: Option<Colors>,
    inactive: Option<Colors>,
    urgent: Option<Colors>,
}

#[derive(Debug, Clone)]
struct BarColor {
    separator: String,
    background: String,
    statusline: String,
    focused_workspace: Option<WorkspaceColor>,
    active_workspace: Option<WorkspaceColor>,
    inactive_workspace: Option<WorkspaceColor>,
    urgent_workspace: Option<WorkspaceColor>,
}

#[derive(Debug, Clone)]
struct WorkspaceColor {
    border: String,
    background: String,
    text: String,
}

#[derive(Debug, Clone)]
struct Theme {
    meta: Option<Meta>,
    colors: Option<Colors>,
    window_colors: Option<WindowColors>,
    bar_colors: Option<BarColor>,
}

fn get_default_config() -> String {
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    let config_path = format!("{}/.config/i3/config", home);
    if Path::new(&config_path).exists() {
        return fs::read_to_string(&config_path).unwrap_or_else(|_| String::new());
    }
    String::new()
}

fn get_theme_by_name(name: &str) -> Option<Theme> {
    let themes = [
        ("slate", include_str!("../assets/themes/slate")),
        ("alphare", include_str!("../assets/themes/alphare")),
        ("ubuntu", include_str!("../assets/themes/ubuntu")),
        ("flat-gray", include_str!("../assets/themes/flat-gray")),
        ("purple", include_str!("../assets/themes/purple")),
        ("archlinux", include_str!("../assets/themes/archlinux")),
        ("default", include_str!("../assets/themes/default")),
        ("debian", include_str!("../assets/themes/debian")),
        ("oceanic-next", include_str!("../assets/themes/oceanic-next")),
        ("base16-tomorrow", include_str!("../assets/themes/base16-tomorrow")),
        ("okraits", include_str!("../assets/themes/okraits")),
        ("icelines", include_str!("../assets/themes/icelines")),
        ("solarized", include_str!("../assets/themes/solarized")),
        ("deep-purple", include_str!("../assets/themes/deep-purple")),
        ("tomorrow-night-80s", include_str!("../assets/themes/tomorrow-night-80s")),
        ("seti", include_str!("../assets/themes/seti")),
        ("lime", include_str!("../assets/themes/lime")),
        ("gruvbox", include_str!("../assets/themes/gruvbox")),
        ("mate", include_str!("../assets/themes/mate")),
    ];

    for (theme_name, theme_content) in themes {
        if theme_name == name {
            return Some(parse_theme(theme_content));
        }
    }
    None
}

fn parse_theme(theme_content: &str) -> Theme {
    let mut meta = None;
    let mut colors = None;
    let mut window_colors = None;
    let mut bar_colors = None;

    let lines: Vec<&str> = theme_content.lines().collect();
    let mut in_meta = false;
    let mut in_colors = false;
    let mut in_window_colors = false;
    let mut in_bar_colors = false;

    for line in lines {
        let trimmed = line.trim();

        if trimmed.starts_with("meta {") {
            in_meta = true;
            continue;
        }

        if in_meta && trimmed == "}" {
            in_meta = false;
            continue;
        }

        if in_meta && trimmed.starts_with("description") {
            if let Some(desc) = trimmed.split(' ').nth(1) {
                meta = Some(Meta {
                    description: desc.to_string(),
                });
            }
            continue;
        }

        if trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_colors && trimmed == "}" {
            in_colors = false;
            continue;
        }

        if in_colors {
            if let Some(color) = trimmed.split(' ').nth(1) {
                if let Some(c) = &mut colors {
                    if trimmed.starts_with("background") {
                        c.background = color.to_string();
                    } else if trimmed.starts_with("foreground") {
                        c.foreground = color.to_string();
                    } else if trimmed.starts_with("focused_border") {
                        c.focused_border = color.to_string();
                    } else if trimmed.starts_with("focused_text") {
                        c.focused_text = color.to_string();
                    } else if trimmed.starts_with("focused_background") {
                        c.focused_background = color.to_string();
                    } else if trimmed.starts_with("active_border") {
                        c.active_border = color.to_string();
                    } else if trimmed.starts_with("active_text") {
                        c.active_text = color.to_string();
                    } else if trimmed.starts_with("active_background") {
                        c.active_background = color.to_string();
                    } else if trimmed.starts_with("inactive_border") {
                        c.inactive_border = color.to_string();
                    } else if trimmed.starts_with("inactive_text") {
                        c.inactive_text = color.to_string();
                    } else if trimmed.starts_with("inactive_background") {
