fn parse_workspace_color(line: &str) -> WorkspaceColor {
    let parts: Vec<&str> = line.split(' ').collect();
    let border = parts.get(1).unwrap_or(&"black".to_string()).to_string();
    let background = parts.get(2).unwrap_or(&"black".to_string()).to_string();
    let text = parts.get(3).unwrap_or(&"white".to_string()).to_string();
    WorkspaceColor {
        border,
        background,
        text,
    }
}

