    let mut workspace_colors: HashMap<String, Vec<String>> = HashMap::new();

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            continue;
        }

        if in_bar && trimmed == "}" {
            in_bar = false;
            in_colors = false;
            continue;
        }

        if in_bar && trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_colors && trimmed == "}" {
            in_colors = false;
            continue;
        }

        if in_colors {
            if trimmed.starts_with("separator") {
                if let Some(bc) = theme.bar_colors.as_ref() {
                    bar_colors.insert("separator".to_string(), bc.separator.clone());
