                    if let Some(aws) = bc.active_workspace.as_ref() {
                        workspace_colors.insert("active_workspace".to_string(), vec![
                            aws.border.clone(),
                            aws.background.clone(),
                            aws.text.clone(),
                        ]);
                    }
                }
            } else if trimmed.starts_with("inactive_workspace") {
