        let theme = get_theme_by_name(&theme_name).unwrap_or_else(|| parse_theme(include_str!("../assets/themes/default")));
        let result = apply_theme(&config_content, &theme);
        println!("{}", result);
        return;
    }

    let theme = get_theme_by_name(&theme_name).unwrap_or_else(|| parse_theme(include_str!("../assets/themes/default")));
    let result = apply_theme(&config_path, &theme);

    if let Some(output_path) = output {
        if let Err(e) = fs::write(&output_path, &result) {
            eprintln!("Error writing to {}: {}", output_path, e);
            process::exit(1);
        }
    }

    if reload {
        let i3_cmd = format!("i3 -C -c {}", result);
        let output = std::process::Command::new("sh")
            .arg("-c")
            .arg(&i3_cmd)
            .output();
        match output {
            Ok(out) => {
                if out.status.success() {
                    println!("Theme applied successfully");
                } else {
                    eprintln!("Error applying theme: {}", String::from_utf8_lossy(&out.stderr));
                    process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("Error applying theme: {}", e);
                process::exit(1);
            }
        }
    }

    if save {
        let input_path = if config_path.is_empty() {
            String::new()
        } else {
            config_path.clone()
        };
        let output_path = if input_path.is_empty() {
            String::new()
        } else {
            input_path.clone()
        };
        if let Err(e) = fs::write(&output_path, &result) {
            eprintln!("Error writing to {}: {}", output_path, e);
            process::exit(1);
        }
    }

    if !output.is_none() && !reload {
        if let Err(e) = validate_config(&result) {
            eprintln!("{}", e);
            process::exit(1);
        }
    }
}

fn apply_theme(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    if let Some(ref meta) = theme.meta {
        result = result.replace("meta {", &format!("meta {{ description: \"{}\" }}", meta.description));
    }

    if let Some(ref colors) = theme.colors {
        result = result.replace("colors {", "colors {");
        result = result.replace("background", &format!("background {}", colors.background));
        result = result.replace("foreground", &format!("foreground {}", colors.foreground));
        result = result.replace("focused_border", &format!("focused_border {}", colors.focused_border));
        result = result.replace("focused_text", &format!("focused_text {}", colors.focused_text));
        result = result.replace("focused_background", &format!("focused_background {}", colors.focused_background));
        result = result.replace("active_border", &format!("active_border {}", colors.active_border));
        result = result.replace("active_text", &format!("active_text {}", colors.active_text));
        result = result.replace("active_background", &format!("active_background {}", colors.active_background));
        result = result.replace("inactive_border", &format!("inactive_border {}", colors.inactive_border));
        result = result.replace("inactive_text", &format!("inactive_text {}", colors.inactive_text));
        result = result.replace("inactive_background", &format!("inactive_background {}", colors.inactive_background));
        result = result.replace("urgent_border", &format!("urgent_border {}", colors.urgent_border));
        result = result.replace("urgent_text", &format!("urgent_text {}", colors.urgent_text));
        result = result.replace("urgent_background", &format!("urgent_background {}", colors.urgent_background));
    }

    if let Some(ref window_colors) = theme.window_colors {
        if let Some(ref focused) = window_colors.focused {
            result = result.replace("focused {", &format!("focused {{ border: {} background: {} text: {} }}", focused.border, focused.background, focused.text));
        }
        if let Some(ref active) = window_colors.active {
            result = result.replace("active {", &format!("active {{ border: {} background: {} text: {} }}", active.border, active.background, active.text));
        }
        if let Some(ref inactive) = window_colors.inactive {
            result = result.replace("inactive {", &format!("inactive {{ border: {} background: {} text: {} }}", inactive.border, inactive.background, inactive.text));
        }
        if let Some(ref urgent) = window_colors.urgent {
            result = result.replace("urgent {", &format!("urgent {{ border: {} background: {} text: {} }}", urgent.border, urgent.background, urgent.text));
        }
    }

    if let Some(ref bar_colors) = theme.bar_colors {
        result = result.replace("bar_colors {", "bar_colors {");
        result = result.replace("separator", &format!("separator {}", bar_colors.separator));
        result = result.replace("background", &format!("background {}", bar_colors.background));
        result = result.replace("statusline", &format!("statusline {}", bar_colors.statusline));
        if let Some(ref focused) = bar_colors.focused_workspace {
            result = result.replace("focused_workspace {", &format!("focused_workspace {{ border: {} background: {} text: {} }}", focused.border, focused.background, focused.text));
        }
        if let Some(ref active) = bar_colors.active_workspace {
            result = result.replace("active_workspace {", &format!("active_workspace {{ border: {} background: {} text: {} }}", active.border, active.background, active.text));
        }
        if let Some(ref inactive) = bar_colors.inactive_workspace {
            result = result.replace("inactive_workspace {", &format!("inactive_workspace {{ border: {} background: {} text: {} }}", inactive.border, inactive.background, inactive.text));
        }
        if let Some(ref urgent) = bar_colors.urgent_workspace {
            result = result.replace("urgent_workspace {", &format!("urgent_workspace {{ border: {} background: {} text: {} }}", urgent.border, urgent.background, urgent.text));
        }
    }

    result
}
ENDOFFILE"}

