fn validate_config(config_path: &str) -> Result<(), String> {
    let i3_cmd = format!("i3 -C -c {}", config_path);

    let output = std::process::Command::new("sh")
        .arg("-c")
        .arg(&i3_cmd)
        .output();

    match output {
        Ok(out) => {
            if out.status.success() {
                Ok(())
            } else {
                Err(format!("Could not validate config with `{}`", i3_cmd))
            }
        }
        Err(_) => Err(format!("Could not validate config with `{}`", i3_cmd)),
    }
}

fn parse_args() -> (Option<String>, Option<String>, Option<String>, Option<String>, bool, bool, bool) {
    let args: Vec<String> = env::args().collect();
