}

fn get_default_config() -> String {
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    let config_path = format!("{}/.config/i3/config", home);
    if Path::new(&config_path).exists() {
        return fs::read_to_string(&config_path).unwrap_or_else(|_| String::new());
    }
    String::new()
}

