    }

    colors
}

fn generate_theme(colors: &HashMap<String, String>) -> String {
    let mut theme = String::new();

    theme.push_str("# i3 config file (v4)\n");
    theme.push_str("#\n");
    theme.push_str("# Please see http://i3wm.org/docs/userguide.html for a complete reference!\n");
    theme.push_str("#\n");
    theme.push_str("# This config file uses keycodes (bindsym) and was written for the QWERTY\n");
    theme.push_str("# layout.\n");
    theme.push_str("#\n");
    theme.push_str("# To get a config file with the same key positions, but for your current\n");
    theme.push_str("# layout, use the i3-config-wizard\n");
    theme.push_str("#\n");
    theme.push_str("\n");
    theme.push_str("# Font for window titles. Will also be used by the bar unless a different font\n");
    theme.push_str("# is used in the bar {} block below. ISO 10646 = Unicode\n");
    theme.push_str("font -misc-fixed-medium-r-normal--13-120-75-75-C-70-iso10646-1\n");
    theme.push_str("# The font above is very space-efficient, that is, it looks good, sharp and\n");
    theme.push_str("# clear in small sizes. However, if you need a lot of unicode glyphs or\n");
    theme.push_str("# right-to-left text rendering, you should instead use pango for rendering and\n");
    theme.push_str("# chose a FreeType font, such as:\n");
    theme.push_str("# font pango:DejaVu Sans Mono 10\n");
    theme.push_str("\n");
    theme.push_str("# use Mouse+Mod1 to drag floating windows to their wanted position\n");
    theme.push_str("floating_modifier Mod1\n");
    theme.push_str("\n");
    theme.push_str("# start a terminal\n");
    theme.push_str("bindsym Mod1+Return exec i3-sensible-terminal\n");
    theme.push_str("\n");
    theme.push_str("# kill focused window\n");
    theme.push_str("bindsym Mod1+Shift+q kill\n");
    theme.push_str("\n");
    theme.push_str("# start dmenu (a program launcher)\n");
    theme.push_str("bindsym Mod1+d exec dmenu_run\n");
    theme.push_str("# There also is the (new) i3-dmenu-desktop which only displays applications\n");
