`src/main.rs` lines 150-200: Theme generation with color substitution
```
fn generate_theme(colors: &HashMap<String, String>) -> String {
    let mut theme = String::new();

    theme.push_str("# i3 config file (v4)\n");
    // ... standard i3 config template
    theme.push_str("bar {\n");
    theme.push_str("        status_command i3status\n");
    theme.push_str("  colors {\n");
    theme.push_str(&format!("    separator {}\n", colors.get("separator").unwrap_or(&"#AAAAAA".to_string())));
    theme.push_str(&format!("    background {}\n", colors.get("background").unwrap_or(&"#222133".to_string())));
    // ... more color substitutions
    theme.push_str("  }\n");
    theme.push_str("}\n");

    theme
}
